<div class="panel"><h2>Buat backup database</h2><form method="post" action="<?= e(url('admin/backup/buat')) ?>"><?= Csrf::field() ?><button class="btn btn-primary" type="submit"><?= icon('database', 14) ?> Buat Backup Sekarang</button></form>
<p class="hint">File backup disimpan di storage/backups (tidak dapat diakses publik). Berkas unggahan (folder uploads) perlu dicadangkan terpisah.</p></div>
<div class="panel"><h2>Daftar backup</h2><div class="table-wrap"><table class="t"><thead><tr><th>File</th><th>Ukuran</th><th>Waktu</th><th></th></tr></thead><tbody>
<?php if (!$files): ?><tr><td colspan="4" class="muted">Belum ada backup.</td></tr><?php endif; ?>
<?php foreach ($files as $f): ?><tr><td><?= e($f['name']) ?></td><td><?= number_format($f['size'] / 1024, 0) ?> KB</td><td><?= e(date('d M Y H:i', $f['time'])) ?></td><td class="act"><a class="btn btn-sm btn-outline" href="<?= e(url('admin/backup/unduh/' . $f['name'])) ?>"><?= icon('download', 13) ?> Unduh</a>
<form method="post" action="<?= e(url('admin/backup/restore')) ?>" data-confirm="Restore akan MENIMPA seluruh database. Lanjutkan?"><?= Csrf::field() ?><input type="hidden" name="file" value="<?= e($f['name']) ?>"><input type="hidden" name="confirm" value="RESTORE"><button class="btn btn-sm btn-danger" type="submit">Restore</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="panel danger-zone"><h2>Restore dari file .sql</h2><form class="form" method="post" action="<?= e(url('admin/backup/restore')) ?>" enctype="multipart/form-data" data-confirm="Restore akan MENIMPA seluruh database. Lanjutkan?"><?= Csrf::field() ?>
<div class="field"><label>File backup (.sql, dibuat oleh fitur ini)</label><input type="file" name="sql" accept=".sql" required></div><div class="field"><label>Ketik RESTORE untuk konfirmasi</label><input name="confirm" required autocomplete="off"></div><button class="btn btn-danger" type="submit">Restore</button></form></div>
